  1	#pragma once
  2	
  3	// What OrcaSlicer tells the person while the JusPrin view is on screen.
  4	//
  5	// OrcaSlicer speaks in one of two ways. It opens a modal box in the same call
  6	// that decided to speak, or it puts the message off: GUI::show_error,
  7	// GUI_App::show_dialog and GUI_App::push_notification queue the box and
  8	// return. JusPrin takes the message at the last point where its reason is
  9	// still known. For a box opened at once that is the modal hook every dialog
 10	// passes (Workspace/DialogListeners.hpp), because the code that asked is still
 11	// running. For a message put off it is one line at the top of each of the
 12	// three functions, which hands the message here while its caller is still on
 13	// the stack.
 14	//
 15	// The reason is a cause, noted at the doors where work comes in: a printer's
 16	// answer to a connection (Printers::record_connection_event), a printer's
 17	// reply (push_notification is given the printer), the network plug-in's
 18	// message (GUI_App::process_network_msg), a slice that ended in an error and a
 19	// failed upload to a print host (JusPrin's listeners of those events, which
 20	// run before OrcaSlicer's own). A person's click in OrcaSlicer's own menus has no cause.
 21	//
 22	// The rule at the hook, for a window no listener answered:
 23	// - A file or folder picker, a window with fields, and a question with a
 24	//   choice are the person's, and open as OrcaSlicer's.
 25	// - A message with only OK is taken, unless another window is open over the
 26	//   main one: a box then belongs with that window, where the person is looking.
 27	// - "Transfer or discard changes", and the unsaved-changes question OrcaSlicer
 28	//   asks before it reloads presets, are answered after a version of the
 29	//   project is saved: the setting changes are dropped and the version keeps
 30	//   them. When no version can be saved, nothing changes and the failure is
 31	//   reported as unexpected.
 32	// - JusPrin's own windows (OwnDialogs.hpp) are never taken.
 33	//
 34	// What becomes of a taken message is the view's: see MessageRoutes.hpp.
 35	//
 36	// GUI thread only.
 37	
 38	#include <wx/string.h>
 39	
 40	#include <functional>
 41	#include <optional>
 42	#include <string>
 43	#include <vector>
 44	
 45	class wxDialog;
 46	class wxWindow;
 47	
 48	namespace Slic3r {
 49	class MachineObject;
 50	}
 51	
 52	namespace Slic3r::GUI::JusPrin::OrcaMessages {
 53	
 54	// What the app was handling when OrcaSlicer spoke. Noted by the code at the
 55	// source, the only place that knows it.
 56	struct Cause
 57	{
 58	    enum class Kind { None, PrinterConnection, PrinterMessage, PluginMessage, Slice, HostUpload };
 59	    Kind        kind{Kind::None};
 60	    std::string printer; // a Bambu device id, or a print host's address
 61	    std::string detail;  // the plug-in's message code, the connection's answer
 62	    // The code that noted the cause tells the person itself: the print issues
 63	    // tell a failed slice, the printer chat the answer to the connection it
 64	    // is waiting for. Not shown again.
 65	    bool        told_elsewhere{false};
 66	};
 67	const char* cause_name(Cause::Kind kind);
 68	
 69	// The cause of what is said while this lives.
 70	class ScopedCause
 71	{
 72	public:
 73	    ScopedCause(Cause::Kind kind, std::string printer, std::string detail);
 74	    ~ScopedCause();
 75	    ScopedCause(const ScopedCause&)            = delete;
 76	    ScopedCause& operator=(const ScopedCause&) = delete;
 77	
 78	private:
 79	    Cause        m_cause;
 80	    ScopedCause* m_outer{nullptr};
 81	    friend Cause current_cause();
 82	};
 83	
 84	// The cause until the event now being handled has ended: for a listener that
 85	// returns before OrcaSlicer's own handler of the same event runs.
 86	void  note_cause(Cause cause);
 87	Cause current_cause();
 88	
 89	// One thing OrcaSlicer wanted to tell the person, taken before its window
 90	// opened, with the reason it was said.
 91	struct TakenMessage
 92	{
 93	    enum class From { Box, ErrorBox, AppDialog, PrinterNotification, UnsavedChanges, Tip, PageSwitch };
 94	    From        from{From::Box};
 95	    Cause       cause;
 96	    std::string title;
 97	    std::string text;
 98	};
 99	const char* from_name(TakenMessage::From from);
100	
101	// What the rule makes of a window.
102	enum class WindowKind { Own, Picker, Chooser, UnsavedChanges, CopyQuestion, Tip, Window, Question, Message, MessageOverWindow };
103	WindowKind  window_kind(wxDialog& dialog);
104	const char* window_kind_name(WindowKind kind);
105	
106	// A window of OrcaSlicer's that reached the person while the view takes
107	// messages, what the rule made of it, and why it was shown.
108	struct ShownWindow
109	{
110	    std::string window_class;
111	    std::string title;
112	    WindowKind  kind{WindowKind::Window};
113	    std::string why;
114	};
115	
116	// What the view gives while it is installed.
117	struct View
118	{
119	    // Called before OrcaSlicer drops setting changes that sit on a profile:
120	    // saves a version that keeps them, or reports why it could not and
121	    // returns false, and then nothing is dropped. The same function guards a
122	    // project's close (ShellController::save_before_dropping_changes).
123	    std::function<bool()> save_before_dropping_changes;
124	    // Told of each message as it is taken.
125	    std::function<void(const TakenMessage&)> show;
126	};
127	void install(View view);
128	void uninstall();
129	
130	// A switch that changes OrcaSlicer's state before OrcaSlicer asks about the
131	// changes it drops saves the version itself, before that change: the sidebar
132	// sequence a filament switch runs renames the filament slot first, and a
133	// version saved at the question would keep the new filament's name with the
134	// old one's settings. While this scope lives the question is answered without
135	// saving again. False when no version could be saved: the view has reported
136	// why, and the switch must not go on. Saves nothing while not taking.
137	class SavedFirst
138	{
139	public:
140	    SavedFirst();
141	    ~SavedFirst();
142	    SavedFirst(const SavedFirst&)            = delete;
143	    SavedFirst& operator=(const SavedFirst&) = delete;
144	    explicit operator bool() const { return m_saved; }
145	
146	private:
147	    bool m_saved{true};
148	    bool m_holding{false};
149	};
150	// Installed, and taking messages.
151	bool taking();
152	// Tests only: turns the taking off and on while the view stays installed, so
153	// OrcaSlicer's own windows open as they do in the classic view.
154	void set_taking_for_tests(bool on);
155	
156	// -- The hand-over points, called from OrcaSlicer's files through
157	//    OrcaHooks.hpp. Each returns true when the message was taken, and
158	//    OrcaSlicer's window must not open. ------------------------------------
159	
160	// GUI_App::process_network_msg: what a box opened below it is about.
161	[[nodiscard]] ScopedCause plugin_message_cause(const std::string& device_id, const std::string& code);
162	// GUI_App::show_dialog.
163	bool take_app_message(const wxString& text);
164	// GUI_App::push_notification, with the printer it was given.
165	bool take_printer_message(const MachineObject* printer, const wxString& text, const wxString& title);
166	// GUI::show_error, through report_error_box (Workspace/FileLoads.hpp).
167	bool take_error(const std::string& text, wxWindow* parent);
168	
169	// The modal hook's rule for a window no listener answered: the id ShowModal
170	// returns instead of showing it, or nothing to show it. A window a listener
171	// chose to show (`shown_by_listener`) is shown, and written down with what
172	// the rule would have made of it.
173	std::optional<int> take_modal(wxDialog& dialog, bool shown_by_listener);
174	
175	// A switch of the main window to OrcaSlicer's page `page` was refused.
176	void note_refused_page(const std::string& page);
177	
178	// Everything taken and let through in this run, for tests.
179	const std::vector<TakenMessage>& taken_messages();
180	const std::vector<ShownWindow>&  shown_windows();
181	
182	
183	} // namespace Slic3r::GUI::JusPrin::OrcaMessages
