  3	// Where the JusPrin view shows a message it took from OrcaSlicer
  4	// (OrcaMessages.hpp): in the project chat, as an entry of the kind the app's
  5	// own work leaves there (Agent::AgentHost::begin_work), ended failed and
  6	// carrying OrcaSlicer's words. The entry goes to the chat on screen, or to
  7	// the empty chat when none is open, and the chat pane opens for it. On Home
  8	// the pane is not shown; the entry is saved with the project and is there
  9	// when the person opens it.
 10	//
 11	// - One about a printer (its answer to a connection, its reply to a command)
 12	//   is titled with the printer's name as JusPrin names it.
 13	// - A failed upload ends the upload's own entry, which follows OrcaSlicer's
 14	//   progress notification, instead of adding a second one.
 15	// - Any other message is titled as OrcaSlicer's window would have been.
 16	// - One whose cause tells the person itself (Cause::told_elsewhere): nothing
 17	//   more.
 18	// - The answered "Transfer or discard changes", a tip, a refused page switch:
 19	//   nothing more.
 20	//
 21	// GUI thread only.
 22	
 23	#include "OrcaMessages.hpp"
 24	
 25	#include <functional>
 26	#include <string>
 27	
 28	namespace Slic3r::GUI::JusPrin::OrcaMessages {
 29	
 30	struct Routes
 31	{
 32	    // The chat's entry for work outside it: begin returns its id, finish
 33	    // ends it with a state (done, cancelled, failed) and a detail.
 34	    std::function<std::string(const std::string& kind, const std::string& title)>                    begin_entry;
 35	    std::function<void(const std::string& id, const std::string& state, const std::string& detail)> finish_entry;
 36	    // Ends the entry of the upload whose notification has these words as
 37	    // failed with `detail`; false when there is none.
 38	    std::function<bool(const std::string& notice_text, const std::string& detail)> fail_upload;
 39	};
 40	
 41	// The kinds of chat entry a taken message makes.
 42	inline constexpr const char* kPrinterEntryKind = "printer";
 43	inline constexpr const char* kMessageEntryKind = "message";
 44	
 45	void route(const TakenMessage& message, const Routes& routes);
 46	
 47	// The name the person knows the printer with this Bambu device id by: the
 48	// named printer linked to it, else the name the printer gives itself, else
 49	// the id.
 50	std::string printer_name(const std::string& device_id);
 51	
 52	} // namespace Slic3r::GUI::JusPrin::OrcaMessages
