 11	#include <vector>
 12	
 13	namespace Slic3r::GUI::JusPrin::OrcaMessages {
 14	
 15	std::string printer_name(const std::string& device_id)
 16	{
 17	    for (const Printers::NamedPrinter& printer : Printers::named_printers())
 18	        if (printer.device_id == device_id)
 19	            return printer.name;
 20	    if (DeviceManager* devices = wxGetApp().getDeviceManager())
 21	        if (const MachineObject* machine = devices->get_my_machine(device_id); machine != nullptr && !machine->get_dev_name().empty())
 22	            return machine->get_dev_name();
 23	    return device_id;
 24	}
 25	
 26	void route(const TakenMessage& message, const Routes& routes)
 27	{
 28	    if (message.cause.told_elsewhere)
 29	        return;
 30	    using From = TakenMessage::From;
 31	    if (message.from != From::Box && message.from != From::ErrorBox && message.from != From::AppDialog &&
 32	        message.from != From::PrinterNotification)
 33	        return;
 34	    if (message.cause.kind == Cause::Kind::HostUpload && routes.fail_upload(message.cause.detail, message.text))
 35	        return;
 36	    const bool about_a_printer = (message.cause.kind == Cause::Kind::PrinterConnection || message.cause.kind == Cause::Kind::PrinterMessage) &&
 37	                                 !message.cause.printer.empty();
 38	    // What OrcaSlicer said is something that did not go as asked, which the
 39	    // person reads after the fact: the entry ends as it begins.
 40	    const std::string id = about_a_printer ? routes.begin_entry(kPrinterEntryKind, printer_name(message.cause.printer)) :
 41	                                             routes.begin_entry(kMessageEntryKind, message.title.empty() ? _u8L("Info") : message.title);
 42	    routes.finish_entry(id, "failed", message.text);
 43	}
 44	
 45	} // namespace Slic3r::GUI::JusPrin::OrcaMessages

