 38	namespace Slic3r::GUI::JusPrin::OrcaMessages {
 39	
 40	namespace {
 41	
 42	bool         g_installed = false;
 43	bool         g_taking_for_tests = true;
 44	View         g_view;
 45	// SavedFirst scopes alive: a version holding the changes is already saved.
 46	int          g_saved_first{0};
 47	ScopedCause* g_cause_scope = nullptr;
 48	Cause        g_noted_cause;
 49	unsigned     g_noted_token = 0;
 50	
 51	// Never destroyed: a box may open while statics are torn down at exit.
 52	std::vector<TakenMessage>& taken_store()
 53	{
 54	    static auto* const list = new std::vector<TakenMessage>;
 55	    return *list;
 56	}
 57	std::vector<ShownWindow>& shown_store()
 58	{
 59	    static auto* const list = new std::vector<ShownWindow>;
 60	    return *list;
 61	}
 62	
 63	void take(TakenMessage::From from, std::string title, std::string text)
 64	{
 65	    TakenMessage message{from, current_cause(), std::move(title), std::move(text)};
 66	    BOOST_LOG_TRIVIAL(info) << "JusPrin took OrcaSlicer's message (" << from_name(from) << ", cause " << cause_name(message.cause.kind)
 67	                            << ", printer \"" << message.cause.printer << "\"): " << message.text;
 68	    taken_store().push_back(message);
 69	    if (g_view.show)
 70	        g_view.show(message);
 71	}
 72	
 73	void let_through(wxDialog& dialog, WindowKind kind, const char* why)
 74	{
 75	    const char* type = typeid(dialog).name();
 76	    shown_store().push_back({type, std::string(dialog.GetTitle().ToUTF8().data()), kind, why});
 77	    BOOST_LOG_TRIVIAL(info) << "JusPrin let OrcaSlicer's window \"" << dialog.GetTitle().ToUTF8().data() << "\" (" << type << ") through: " << why;
 78	}
 79	
 80	int count_buttons(wxWindow& window)
 81	{
 82	    int count = 0;
 83	    for (wxWindow* child : window.GetChildren()) {
 84	        if (!child->IsShown())
 85	            continue;
 86	        if (dynamic_cast<::Button*>(child) != nullptr || dynamic_cast<wxButton*>(child) != nullptr)
 87	            ++count;
 88	        count += count_buttons(*child);
 89	    }
 90	    return count;
 91	}
 92	
 93	// Whether the person has another window open over the main one: OrcaSlicer's
 94	// settings window, the send dialog, the monitor, Preferences. A box that
 95	// opens then belongs with that window, where they are looking.
 96	bool another_window_is_open(const wxWindow* parent, const wxWindow* box)
 97	{
 98	    const wxWindow* frame = wxGetApp().mainframe;
 99	    if (parent != nullptr)
100	        if (const wxWindow* top = wxGetTopLevelParent(const_cast<wxWindow*>(parent)); top != nullptr && top != frame && top != box)
101	            return true;
102	    for (const wxWindow* window : wxTopLevelWindows) {
103	        if (window == frame || window == box || !window->IsShown())
104	            continue;
105	        if (dynamic_cast<const wxDialog*>(window) != nullptr || dynamic_cast<const wxFrame*>(window) != nullptr)
106	            return true;
107	    }
108	    return false;
109	}
110	
111	// The two uses of UnsavedChangesDialog that ask what to do with setting
112	// changes not yet saved in a profile: a switch of profile ("Transfer or
113	// discard changes", Tab::may_discard_current_dirty_preset), and the question
114	// before OrcaSlicer reloads profiles ("<caption>: unsaved changes",
115	// GUI_App::check_and_save_current_preset_changes and
116	// check_and_keep_current_preset_changes). The class also asks whether to copy
117	// one nozzle's settings to the other (Tab::sync_excluder), which is a
118	// question about a copy and stays the person's. OrcaSlicer names the uses
119	// only in their titles, so they are told apart by those, looked up as
120	// OrcaSlicer looks them up.
121	enum class UnsavedUse { Switch, BeforeReload, Other };
122	UnsavedUse unsaved_use(const wxDialog& dialog)
123	{
124	    const wxString title = dialog.GetTitle();
125	    if (title == _L("Transfer or discard changes"))
126	        return UnsavedUse::Switch;
127	    if (title.EndsWith(": " + _L("unsaved changes")))
128	        return UnsavedUse::BeforeReload;
129	    return UnsavedUse::Other;
130	}
131	
132	// OrcaSlicer's own Discard, for every profile with unsaved changes.
133	void discard_preset_edits()
134	{
135	    for (Tab* tab : wxGetApp().tabs_list)
136	        if (tab->get_presets() != nullptr && tab->get_presets()->current_is_dirty())
137	            tab->get_presets()->discard_current_changes();
138	    wxGetApp().load_current_presets(false);
139	}
140	
141	// Without a saved version the dialog is cancelled, which leaves the profile
142	// and its changes as they were; the view has reported why.
143	int answer_unsaved_changes(wxDialog& dialog, UnsavedUse use)
144	{
145	    if (g_saved_first == 0 && !g_view.save_before_dropping_changes())
146	        return wxID_CANCEL;
147	    // A switch goes on to drop the outgoing profile's changes itself; the
148	    // other callers read the dialog's choice, which is none, so the changes
149	    // are dropped here.
150	    if (use == UnsavedUse::BeforeReload)
151	        discard_preset_edits();
152	    take(TakenMessage::From::UnsavedChanges, std::string(dialog.GetTitle().ToUTF8().data()),
153	         "A version was saved and the setting changes were dropped.");
154	    return wxID_OK;
155	}
156	
157	} // namespace
