159	const char* cause_name(Cause::Kind kind)
160	{
161	    switch (kind) {
162	    case Cause::Kind::None: return "none";
163	    case Cause::Kind::PrinterConnection: return "printer_connection";
164	    case Cause::Kind::PrinterMessage: return "printer_message";
165	    case Cause::Kind::PluginMessage: return "plugin_message";
166	    case Cause::Kind::Slice: return "slice";
167	    case Cause::Kind::HostUpload: return "host_upload";
168	    }
169	    return "";
170	}
171	
172	const char* from_name(TakenMessage::From from)
173	{
174	    switch (from) {
175	    case TakenMessage::From::Box: return "box";
176	    case TakenMessage::From::ErrorBox: return "error_box";
177	    case TakenMessage::From::AppDialog: return "app_dialog";
178	    case TakenMessage::From::PrinterNotification: return "printer_notification";
179	    case TakenMessage::From::UnsavedChanges: return "unsaved_changes";
180	    case TakenMessage::From::Tip: return "tip";
181	    case TakenMessage::From::PageSwitch: return "page_switch";
182	    }
183	    return "";
184	}
