296	WindowKind window_kind(wxDialog& dialog)
297	{
298	    if (is_own_dialog(dialog))
299	        return WindowKind::Own;
300	    const Workspace::DialogFacts facts = Workspace::read_dialog(dialog);
301	    if (facts.picker)
302	        return WindowKind::Picker;
303	    if (facts.chooser)
304	        return WindowKind::Chooser;
305	    if (dynamic_cast<UnsavedChangesDialog*>(&dialog) != nullptr)
306	        return unsaved_use(dialog) == UnsavedUse::Other ? WindowKind::CopyQuestion : WindowKind::UnsavedChanges;
307	    if (dynamic_cast<TipsDialog*>(&dialog) != nullptr && !facts.yes && !facts.no)
308	        return WindowKind::Tip;
309	    const bool native = dynamic_cast<wxMessageDialogBase*>(&dialog) != nullptr;
310	    if (!native && dynamic_cast<MsgDialog*>(&dialog) == nullptr)
311	        return WindowKind::Window;
312	    const bool only_ok = facts.ok && !facts.yes && !facts.no && !facts.cancel && (native || count_buttons(dialog) == 1);
313	    if (!only_ok)
314	        return WindowKind::Question;
315	    if (current_cause().kind == Cause::Kind::None && another_window_is_open(dialog.GetParent(), &dialog))
316	        return WindowKind::MessageOverWindow;
317	    return WindowKind::Message;
318	}
319	
320	std::optional<int> take_modal(wxDialog& dialog, bool shown_by_listener)
321	{
322	    if (!taking())
323	        return std::nullopt;
324	    const WindowKind kind = window_kind(dialog);
325	    if (kind == WindowKind::Own)
326	        return std::nullopt;
327	    if (shown_by_listener) {
328	        let_through(dialog, kind, "a listener showed it");
329	        return std::nullopt;
330	    }
331	    switch (kind) {
332	    case WindowKind::Own: return std::nullopt;
333	    case WindowKind::Picker:
334	    case WindowKind::Chooser: let_through(dialog, kind, "a picker"); return std::nullopt;
335	    case WindowKind::UnsavedChanges: return answer_unsaved_changes(dialog, unsaved_use(dialog));
336	    case WindowKind::CopyQuestion: let_through(dialog, kind, "a question about copying settings"); return std::nullopt;
337	    case WindowKind::Tip: {
338	        const Workspace::DialogFacts facts = Workspace::read_dialog(dialog);
339	        take(TakenMessage::From::Tip, facts.title, facts.text);
340	        return wxID_OK;
341	    }
342	    case WindowKind::Window: let_through(dialog, kind, "a window"); return std::nullopt;
343	    case WindowKind::Question: let_through(dialog, kind, "a question"); return std::nullopt;
344	    case WindowKind::MessageOverWindow: let_through(dialog, kind, "a message, with another window open"); return std::nullopt;
345	    case WindowKind::Message: {
346	        const Workspace::DialogFacts facts = Workspace::read_dialog(dialog);
347	        take(TakenMessage::From::Box, facts.title, facts.text);
348	        return wxID_OK;
349	    }
350	    }
351	    return std::nullopt;
352	}
